"use client";

const values = [42, 45, 41, 48, 52, 49, 55, 53, 58, 62, 57, 64, 61, 67, 72, 69, 75, 78, 74, 81, 86, 83, 89, 94];
const W = 260, H = 64, P = 6;
const min = Math.min(...values), max = Math.max(...values);
const pts = values.map((v, i) => [P + (i / (values.length - 1)) * (W - 2 * P), P + (1 - (v - min) / (max - min)) * (H - 2 * P)]);
const d = pts.map(([x, y], i) => `${i ? "L" : "M"}${x},${y}`).join("");

export function SparklineTailwind() {
  const [x, y] = pts[pts.length - 1];
  return (
    <div className="inline-flex flex-col gap-3 rounded-xl border border-zinc-800 bg-zinc-950 p-5 text-zinc-100">
      <span className="text-sm text-zinc-400">Weekly signups</span>
      <span className="text-2xl font-semibold tabular-nums">94 <span className="rounded-full bg-green-500/15 px-2 text-xs text-green-500">+123.8%</span></span>
      <svg width={W} height={H} role="img" aria-label="Weekly signups from 42 to 94" className="overflow-visible">
        <defs><linearGradient id="slg" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stopColor="#6366f1" stopOpacity=".35" /><stop offset="1" stopColor="#6366f1" stopOpacity="0" /></linearGradient></defs>
        <path d={`${d}L${x},${H}L${P},${H}Z`} fill="url(#slg)" className="animate-[fade_.8s_.5s_both] motion-reduce:animate-none" />
        <path d={d} pathLength={1} fill="none" stroke="#6366f1" strokeWidth={2} strokeLinecap="round" strokeDasharray={1} className="animate-[draw_1.2s_ease-in-out_both] motion-reduce:animate-none" />
        <circle cx={x} cy={y} r={3.5} fill="#6366f1" />
      </svg>
      <style>{`@keyframes draw{from{stroke-dashoffset:1}to{stroke-dashoffset:0}}@keyframes fade{from{opacity:0}}`}</style>
    </div>
  );
}
